        Parameter sourceParam = first( method.getSourceParameters() );
        PresenceCheck sourceParameterPresenceCheck =
            PresenceCheckMethodResolver.getPresenceCheckForSourceParameter( method, null, sourceParam, ctx );

        return instantiateMappingMethod(
            method,
            existingVariables,
            assignment,
            factoryMethod,
            mapNullToDefault,
            loopVariableName,
            beforeMappingMethods,
            afterMappingMethods,
            selectionParameters,
            sourceParameterPresenceCheck
        );
    }

    private Assignment forge(SourceRHS sourceRHS, Type sourceType, Type targetType) {
        Assignment assignment = super.forgeMapping( sourceRHS, sourceType, targetType );
        if ( assignment != null ) {
            ctx.getMessager().note( 2, Message.ITERABLEMAPPING_CREATE_ELEMENT_NOTE, assignment );
        }
        return assignment;
    }

    protected abstract M instantiateMappingMethod(Method method, Collection<String> existingVariables,
